import{_ as s,o as e,c as a,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"2.2 花开两朵：切换型阻塞与平衡型阻塞","description":"","frontmatter":{"translationSource":{"title":"2.2 花开两朵：切换型阻塞与平衡型阻塞","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZDxRoi4GKekmLzgHNaf4fQ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking"}]]},"headers":[],"relativePath":"zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking.md","filePath":"zh/page-ZDxRoi4GKekmLzgHNaf4fQ.md"}'),r={name:"zh/2-2-two-branches-bloom-switching-type-and-balancing-type-blocking.md"};function d(n,t,i,l,c,p){return e(),a("div",null,[...t[0]||(t[0]=[o('<div class="logistics-content"><span class="logistics-source-anchor" id="_2-2-花开两朵-切换型阻塞与平衡型阻塞" aria-hidden="true"></span><h1 id="_2-2-花开两朵-切换型阻塞与平衡型阻塞" tabindex="-1">2.2 花开两朵：切换型阻塞与平衡型阻塞 <a class="header-anchor" href="#_2-2-花开两朵-切换型阻塞与平衡型阻塞" aria-label="Permalink to &quot;2\\.2 花开两朵：切换型阻塞与平衡型阻塞&quot;">​</a></h1><blockquote><p>源页面 ID：<code>ZDxRoi4GKekmLzgHNaf4fQ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZDxRoi4GKekmLzgHNaf4fQ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>下面介绍两类生产中常用的阻塞方案。</p><ol><li><p><span class="mark-red"><strong>切换型阻塞</strong></span>（曾用名：第一类阻塞）：在不人为干预的情况下，阻塞发生后<span class="mark-purple"><strong>全部</strong></span>物料流量从一条通路切换到另一条通路，出现生产产品的更换，常用于<strong>实现同材料不同成品生产方案的完全切换，过剩产量留存中间产物等</strong>。</p></li><li><p><span class="mark-red"><strong>平衡型阻塞</strong></span>（曾用名：第二类阻塞）：在不人为干预的情况下，阻塞发生后<span class="mark-purple"><strong>部分</strong></span>物料流量从一条通路切换到另一条通路，达到平衡，没有出现产品的改变，常用于<strong>实现不容易分流得到的流量数值，自适应配平</strong>。平衡型阻塞产线一般用来长期运转下去。</p></li></ol><blockquote><p>注意，以上关于物料流量的转移指的是一段时间内平均下来的视角。从局部的微观尺度角度来说，阻塞发生时全部物品都流向另一条支路，等阻塞的机器消耗原料后阻塞短暂解除，又恢复流量使其重复堵塞。</p></blockquote><p>前一小节所述最小例子属于切换型阻塞。</p><table tabindex="0"><thead><tr><th></th><th><span class="mark-red"><strong>切换型阻塞</strong></span></th><th><span class="mark-red"><strong>平衡型阻塞</strong></span></th></tr></thead><tbody><tr><td>多少物料流量发生切换</td><td>全部</td><td>部分</td></tr><tr><td>主要目的</td><td>不同成品方案切换，留存中间产物或必要零件</td><td>达到特定流量，自适应配平</td></tr><tr><td>设计关注点</td><td><strong>要从什么切换到什么</strong></td><td><strong>如何使初始状态向平衡状态演化</strong></td></tr><tr><td>典型应用</td><td>供给30/m蓝铁矿，先按30/m生产铁零件，<u>铁零件库存满后</u>再按15/m生产蓝铁瓶</td><td>供给60/m蓝铁矿，其中13.75/m用于生产壤晶，46.25/m用于生产蓝药</td></tr><tr><td>稳定状态</td><td>没有稳定状态，先持续生产A，再持续生产B</td><td>达到平衡稳定后，长期平均下来按预定速度生产</td></tr><tr><td>优先级设计</td><td>一般使用优先输出（储存箱优先输出次优送回仓库也是一种）</td><td>优先输出与分流器均可</td></tr><tr><td>设计难度</td><td>简单</td><td>难（需要评估流量与动力稳定性）</td></tr><tr><td>阻塞发生源</td><td>通常是<strong>储存箱</strong>或<strong>仓库</strong></td><td>通常是<strong>机器缓存</strong>或<strong>物流阻塞结构</strong></td></tr><tr><td>两条通路生产需求</td><td><strong>短期内不急着用次优通路的成品</strong></td><td><strong>要尽快一起生产</strong></td></tr></tbody></table><details><summary>ai总结图</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f3e492bba1fa0c43.q90-541e50d5e6be506e.webp" alt="22 花开两朵：切换型阻塞与平衡型阻塞"></p><div class="logistics-image-caption" data-source-block="M7euX5spAWVXU93BZkDVNZ"><p>怎么感觉写半天不如ai</p></div></details><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ea4a1c04901c8a60.q90-5d396658b6731317.webp" alt="22 花开两朵：切换型阻塞与平衡型阻塞"></p><div class="logistics-image-caption" data-source-block="mDH7AAYfk5AR4NQIHpoxX3"><p>平衡型阻塞的典型应用例子，图中从左往右第一个箱子用于优先级输出，第二个箱子用于均分</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b2ec8f623a3ec66d.q90-2320cdd398d6847b.webp" alt="22 花开两朵：切换型阻塞与平衡型阻塞"></p><div class="logistics-image-caption" data-source-block="SUbkP1QmrOReCYsewvt9l3"><p>准入口限流，或者用分汇流阻塞结构限流，也算平衡型阻塞（</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d8ed13533d840ed4.q90-28304f615fe1f868.webp" alt="22 花开两朵：切换型阻塞与平衡型阻塞"></p><div class="logistics-image-caption" data-source-block="6r3gut5DquedlXNC3yJgqD"><p>另一种切换型阻塞典型设计，30/m铁零件生产爆仓后把30/m蓝铁块送回仓库</p></div><p>平衡型阻塞的特点是阻塞形成时<strong>两条通路均仍平衡在一定速度的物料消耗与成品生产</strong>，因此阻塞源常形成在产线的中间部分，包括<strong>在连接机器的阻塞型物流结构阻塞，机器本身的生产速度不足导致缓存阻塞，</strong><u><strong>或多原料配方时其余原料的供给不足导致缓存阻塞</strong></u>。需要注意的是，在无手动干预的情况下，阻塞型物流结构和机器生产速度无法自发调节，因此前两种设计复杂程度低，系统行为表现简单，但不具备根据其他物料流量控制生产速度的能力。</p><p>对于两类阻塞，在规划好生产优先顺序，并合理应用<strong>优先级</strong>布局设计（见本节附录）的情况下，都可以得到稳定可靠的阻塞生产产线。但对于平衡型阻塞，也可以<strong>使用分流结构替代优先级</strong>来极大地简化设计，详见2.5节。</p><p><span class="mark-red">两类阻塞也可以一起使用</span>。例如言老大的智能切换产线中（<a href="/endfield-skydoc/zh/some-simpler-adaptive-setups#source-block-ZJVOO6eIEMkLMbQvKmSE1N">较简单的自适应装置们</a>），赫铜零件不足时，先生产赫铜和灼铜零件和重息壤，在产线运行时表现为平衡型阻塞。而赫铜零件填充满仓库后，所有流向赫铜零件的铜原料都转向灼铜零件生产，也体现了切换型阻塞的性质。</p><p><a href="/endfield-skydoc/zh/2-1-hello-world-ferrium-ore-at-a-fork-in-the-road">2.1 Hello World：蓝铁矿的命途分叉</a></p><p><a href="/endfield-skydoc/zh/2-3-the-controlled-controlled-branch-and-the-unfree-free-branch">2.3 受控的受控端 &amp; 不自由的自由端 （考虑弃用）</a></p></div>',1)])])}const m=s(r,[["render",d]]);export{h as __pageData,m as default};
